    def __init__(self, subject: "UiApp", parent: "UiAppView", **kwargs):
        super().__init__(subject, parent, **kwargs)
        self.root_view: UiAppView = parent
        self.s = subject
        self.selected_panel_name = ""
        self.selected_panel = None
        self.selected_project_id: int | None = None
        self._active_project_filter: int | None = None
        self.project_selector = ProjectSelector(subject=self.subject, parent=self)
        self.panels = dict(
            profiles = SidebarPanelAgents(subject=self.subject, parent=self),
            chat = SidebarPanelChats(subject=self.subject, parent=self),
            cron = SidebarPanelCronjobs(subject=self.subject, parent=self),
            dataflows = SidebarPanelCollections(subject=self.subject, parent=self),
            insights = SidebarPanelInsights(subject=self.subject, parent=self),
            logs = SidebarPanelLogs(subject=self.subject, parent=self),
            projects = SidebarPanelProjects(subject=self.subject, parent=self),
            workspaces = SidebarPanelWorkspaces(subject=self.subject, parent=self),
            settings = SidebarPanelSettings(subject=self.subject, parent=self),
            skills = SidebarPanelSkills(subject=self.subject, parent=self),
        )
        self.switchPanel("chat")

    def switchPanel(self, panel_name):
        if panel_name not in self.panels:
            print(f"No panel named {panel_name}")
            return 
        self.selected_panel_name = panel_name
        self.selected_panel = self.panels[panel_name]
        if hasattr(self.selected_panel, "panel_activated"):
            self.selected_panel.panel_activated()
        self.parent.rail.update()
        self.update()

    def set_project(self, project_id: int | None) -> None:
        self.selected_project_id = project_id
        if project_id != self._active_project_filter:
            self._active_project_filter = project_id
            self._apply_project_filter()

    def _apply_project_filter(self) -> None:
        pid = self.selected_project_id
        for panel in self.panels.values():
            if hasattr(panel, "set_project_filter"):
                panel.set_project_filter(pid)

